input.sparql:
SELECT ?zone ?point ?ref ?tsid ?name WHERE {
  ?zone a brick:Zone ; brick:hasName ?name .
  FILTER(CONTAINS(?name, "Perimeter_mid_ZN_3"))
  ?point brick:isPointOf ?zone ; a brick:Air_Temperature_Sensor .
  ?point ref:hasTimeseriesId ?tsid .
}

SELECT ?point ?name ?tsid WHERE {
  ?point a brick:Air_Temperature_Sensor .
  ?point ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?point brick:hasName ?name }
} LIMIT 20

